<script>
function adata(x){return x?JSON.parse(atob(x)):{}}function clearAwardErrors(){document.querySelectorAll('#awardForm .award-invalid').forEach(x=>x.classList.remove('award-invalid'));document.querySelectorAll('#awardForm .award-error').forEach(x=>x.remove())}function openAward(mode,encoded){var f=document.getElementById('awardForm'),d=adata(encoded);f.reset();clearAwardErrors();f.action=@json(route('awards.store'));document.getElementById('awardMethod').innerHTML='';document.getElementById('awardTitle').textContent=mode==='edit'?'Edit Award':'Add New Award';['employee_id','award_type_id','award_date','gift','description'].forEach(k=>f.elements[k].value=d[k]||'');if(mode==='edit'){f.action=@json(route('awards.update','__ID__')).replace('__ID__',d.id);document.getElementById('awardMethod').innerHTML='<input type="hidden" name="_method" value="PUT">'}}function viewAward(encoded){var d=adata(encoded),m=document.getElementById('awardView');m.querySelector('[data-view=employee]').textContent=(d.employee_name||'—')+(d.employee_email?' — '+d.employee_email:'');m.querySelector('[data-view=type]').textContent=d.award_type||'—';m.querySelector('[data-view=date]').textContent=d.award_date||'—';m.querySelector('[data-view=gift]').textContent=d.gift||'—';m.querySelector('[data-view=description]').textContent=d.description||'—';var files=m.querySelector('[data-view=files]');files.innerHTML='';[['certificate_path','Certificate'],['photo_path','Photo']].forEach(x=>{if(d[x[0]]){var a=document.createElement('a');a.className='btn btn-sm btn-light-primary me-2';a.target='_blank';a.href=@json(asset('storage'))+'/'+d[x[0]];a.textContent='View '+x[1];files.appendChild(a)}})}
document.addEventListener('DOMContentLoaded',function(){var f=document.getElementById('awardForm'),rules={employee_id:x=>x.value?'':'Employee is required',award_type_id:x=>x.value?'':'Award Type is required',award_date:x=>x.value?'':'Award Date is required',gift:x=>x.value.trim().length>191?'Gift may not exceed 191 characters':'',description:x=>!x.value.trim()?'Description is required':(x.value.trim().length>2000?'Description may not exceed 2000 characters':''),certificate:x=>x.files[0]&&x.files[0].size>5242880?'Certificate may not exceed 5 MB':'',photo:x=>x.files[0]&&x.files[0].size>5242880?'Photo may not exceed 5 MB':''};function valid(x){var msg=rules[x.name](x),e=x.parentElement.querySelector('.award-error');if(!e){e=document.createElement('div');e.className='award-error';x.after(e)}x.classList.toggle('award-invalid',!!msg);e.textContent=msg;e.style.display=msg?'block':'none';return !msg}Object.keys(rules).forEach(n=>['input','change','blur'].forEach(ev=>f.elements[n].addEventListener(ev,()=>valid(f.elements[n]))));f.addEventListener('submit',function(e){var first=null;Object.keys(rules).forEach(n=>{if(!valid(f.elements[n])&&!first)first=f.elements[n]});if(first){e.preventDefault();first.focus()}});document.querySelectorAll('.award-delete').forEach(df=>df.addEventListener('submit',function(e){if(df.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete this award?',icon:'warning',showCancelButton:true}).then(r=>{if(r.isConfirmed){df.dataset.ok=1;df.submit()}})}))});
</script>
<script>
document.addEventListener('DOMContentLoaded',function(){
 var filterForm=document.querySelector('.awards-page form[method="GET"]'),search=filterForm?.querySelector('[name="search"]');
 if(search){var searchWrap=document.createElement('div');searchWrap.className='award-search-wrap';search.parentNode.insertBefore(searchWrap,search);searchWrap.appendChild(search);var searchIcon=document.createElement('span');searchIcon.className='award-search-icon';searchIcon.innerHTML='<svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"></circle><path d="m20 20-4-4"></path></svg>';searchWrap.prepend(searchIcon);search.style.width='100%';search.style.paddingLeft='42px';search.placeholder='Search...'}
 if(filterForm){var active=[...new URLSearchParams(window.location.search).entries()].some(function(item){return item[0]!=='page'&&item[1]!==''});if(active){var clear=document.createElement('a');clear.href=@json(route('awards'));clear.className='btn btn-light-danger';clear.textContent='Clear';filterForm.appendChild(clear)}}
 var viewModal=document.getElementById('awardView'),heading=viewModal.querySelector('.modal-header h2');
 var icon=document.createElement('span');icon.className='award-view-icon';icon.innerHTML='<svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="5"/><path d="m8.5 12-1 9 4.5-2.5L16.5 21l-1-9"/></svg>';heading.parentElement.classList.add('d-flex','align-items-center','gap-3');heading.before(icon);heading.textContent='Award Details';
 ['certificate','photo'].forEach(function(name){var input=document.querySelector('#awardForm [name="'+name+'"]'),hidden=document.createElement('input'),preview=document.createElement('img'),remove=document.createElement('button');hidden.type='hidden';hidden.name='remove_'+name;hidden.value='0';preview.className='award-edit-preview';preview.dataset.preview=name;remove.type='button';remove.className='btn btn-light award-remove-file';remove.textContent='×';remove.style.display='none';remove.addEventListener('click',function(){hidden.value='1';input.value='';preview.style.display='none';remove.style.display='none'});var row=document.createElement('div');row.className='award-edit-file';input.parentNode.insertBefore(row,input);row.append(input,hidden,remove);row.after(preview)});
});
function awardAsset(path){return @json(asset('storage')).replace(/\/$/,'')+'/'+path}
function openAward(mode,encoded){var f=document.getElementById('awardForm'),d=adata(encoded);f.reset();clearAwardErrors();f.action=@json(route('awards.store'));document.getElementById('awardMethod').innerHTML='';document.getElementById('awardTitle').textContent=mode==='edit'?'Edit Award':'Add New Award';['employee_id','award_type_id','award_date','gift','description'].forEach(k=>f.elements[k].value=d[k]||'');['certificate','photo'].forEach(function(name){var preview=f.querySelector('[data-preview="'+name+'"]'),remove=f.querySelector('[name="remove_'+name+'"]');remove.value='0';preview.style.display='none';remove.parentElement.querySelector('.award-remove-file').style.display='none';var path=d[name+'_path'];if(path&&/\.(jpe?g|png|webp)$/i.test(path)){preview.src=awardAsset(path);preview.style.display='block';remove.parentElement.querySelector('.award-remove-file').style.display=''}});if(mode==='edit'){f.action=@json(route('awards.update','__ID__')).replace('__ID__',d.id);document.getElementById('awardMethod').innerHTML='<input type="hidden" name="_method" value="PUT">'}}
function viewAward(encoded){var d=adata(encoded),m=document.getElementById('awardView');m.querySelector('[data-view=employee]').textContent=d.employee_name||'—';m.querySelector('[data-view=type]').textContent=d.award_type||'—';m.querySelector('[data-view=date]').textContent=d.award_date||'—';m.querySelector('[data-view=gift]').textContent=d.gift||'—';m.querySelector('[data-view=description]').textContent=d.description||'—';var files=m.querySelector('[data-view=files]');files.innerHTML='';files.className='full award-preview-grid';[['certificate_path','Certificate'],['photo_path','Photo']].forEach(function(item){var section=document.createElement('div'),label=document.createElement('div');label.className='award-label';label.textContent=item[1];section.appendChild(label);if(d[item[0]]){var path=d[item[0]],link=document.createElement('a');link.href=awardAsset(path);link.target='_blank';if(/\.(jpe?g|png|webp)$/i.test(path)){var image=document.createElement('img');image.className='award-preview';image.src=link.href;image.alt=item[1];link.appendChild(image)}else{link.className='btn btn-light-primary';link.textContent='View '+item[1]}section.appendChild(link)}else{var empty=document.createElement('div');empty.className='award-value';empty.textContent='—';section.appendChild(empty)}files.appendChild(section)})}
</script>
